// Authenticated webhook only. Normalize a single bounded document before any database/storage write.
const body=$json.body ?? $json;
const provider=String(body.storage_provider || $env.SIGNATUREGATE_PAPER_STORAGE_PROVIDER || 'nocodb');
if(!['nocodb','google_drive'].includes(provider))throw Error('Choose Google Drive or NocoDB paper storage');
if(provider==='nocodb'){
 const storage=String($env.NOCODB_BASE_URL || '').trim();
 if(!/^https?:\/\/[^/?#@\s]+(?:\/[^?#]*)?$/.test(storage))throw Error('A reviewed NOCODB_BASE_URL is required for NocoDB storage');
}else{
 const folder=String($env.SIGNATUREGATE_PAPER_DRIVE_FOLDER_ID || '').trim();
 if(!/^[A-Za-z0-9_-]{10,200}$/.test(folder))throw Error('A reviewed private Google Drive parent folder is required');
}
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const actor=String(body.actor_email || '').trim().toLowerCase();
if(!actor || actor.length>320 || !uuid.test(body.request_id || '') || !uuid.test(body.member_id || '') || !uuid.test(body.practitioner_person_id || ''))throw Error('Account, request and assigned Participant/practitioner identifiers required');
if(body.agreement_template_id && !uuid.test(body.agreement_template_id))throw Error('Invalid template identifier');
if(!Array.isArray(body.files)||body.files.length!==1)throw Error('Select exactly one PDF, PNG or JPEG document');
const file=body.files[0],name=String(file.name || ''),mimeType=String(file.type || file.mimeType || '');
let data=file.data || file.base64 || file.content;
if(!name || name.length>160 || /[\x00-\x1f\x7f/\\]/.test(name) || typeof data!=='string')throw Error('Document filename and base64 content required');
if(data.startsWith('data:')){
 const match=/^data:([^;,]+);base64,([A-Za-z0-9+/]*={0,2})$/.exec(data);
 if(!match || match[1]!==mimeType)throw Error('Document data URL type mismatch');data=match[2];
}
if(data.length<12 || data.length>6990508 || data.length%4 || !/^[A-Za-z0-9+/]+={0,2}$/.test(data))throw Error('Invalid or oversized document content');
const bytes=Buffer.from(data,'base64');
if(bytes.length>5242880 || bytes.toString('base64')!==data)throw Error('Invalid or oversized document content');
const hex=bytes.subarray(0,8).toString('hex');
if(!((mimeType==='application/pdf' && hex.startsWith('255044462d')) || (mimeType==='image/png' && hex==='89504e470d0a1a0a') || (mimeType==='image/jpeg' && hex.startsWith('ffd8ff'))))throw Error('PDF, PNG or JPEG content must match its type');
return [{json:{actor_email:actor,request_id:body.request_id,storage_provider:provider,payload:{storage_provider:provider,member_id:body.member_id,practitioner_person_id:body.practitioner_person_id,agreement_template_id:body.agreement_template_id || '',files:[{name,mimeType,data}]}}}];

const source=$('Code - Validate Paper Request').first().json;
const file=source.payload.files[0];
const data=await this.helpers.prepareBinaryData(Buffer.from(file.data,'base64'),file.name,file.mimeType);
return [{json:{request_id:source.request_id},binary:{data}}];

// Accept only a real storage response. No caller-provided attachment URL is accepted.
const input=$input.all(),source=$('Code - Validate Paper Request').first().json;
const files=input.flatMap(item=>{const raw=item.json?.body ?? item.json;return Array.isArray(raw)?raw:Array.isArray(raw?.files)?raw.files:[raw];});
if(files.length!==1)throw Error('Storage did not return exactly one attachment; inspect this request before retrying');
if(source.storage_provider!=='nocodb')throw Error('NocoDB response does not match the selected provider');
const path=files[0]?.path;
if(typeof path!=='string'||!/^[A-Za-z0-9_-][A-Za-z0-9_./-]{1,1023}$/.test(path)||path.includes('..')||path.includes('//'))throw Error('Storage did not return a safe relative attachment path');
const file=source.payload.files[0];
return [{json:{actor_email:source.actor_email,request_id:source.request_id,evidence:[{storage_provider:'nocodb',path,title:file.name,mimetype:file.mimeType,size:Buffer.from(file.data,'base64').length}]}}];

// Only the authenticated Drive upload node supplies this reference; no sharing operation is performed.
const input=$input.all(),source=$('Code - Validate Paper Request').first().json;
if(source.storage_provider!=='google_drive' || input.length!==1)throw Error('Drive response does not match the reserved upload');
const stored=input[0].json,folder=String($env.SIGNATUREGATE_PAPER_DRIVE_FOLDER_ID || '').trim();
if(typeof stored.id!=='string'||!/^[A-Za-z0-9_-]{10,200}$/.test(stored.id)||stored.trashed===true || !Array.isArray(stored.parents)||!stored.parents.includes(folder))throw Error('Drive did not confirm the configured parent folder');
const file=source.payload.files[0];
if(stored.mimeType!==file.mimeType || Number(stored.size)!==Buffer.from(file.data,'base64').length)throw Error('Stored Drive file metadata differs from the uploaded document');
return [{json:{actor_email:source.actor_email,request_id:source.request_id,evidence:[{storage_provider:'google_drive',drive_file_id:stored.id,web_url:'https://drive.google.com/file/d/'+stored.id+'/view',title:file.name,mimetype:file.mimeType,size:Number(stored.size)}]}}];
